  }
  other() {
    return 1;
  }
}
";
    let dir = project(&[("src/foo.ts", source)]);
    let result = library_search(&dir, "needle");
    let mut rows: Vec<_> = result
        .ranked
        .iter()
        .map(|r| (r.block.line_start, r.block.line_end, r.block.matched_lines.clone(), r.block.parent.is_some()))
        .collect();
