"""Alternates the old and new binary on the stress/many set and prints the median and min wall ms of each."""
import statistics
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path("/Users/gabe/Projects/monokl/.claude/worktrees/agent-a3f673a53d0186c7c")
DIR = ROOT / "target/bench/stress/many"
bins = {"old": ROOT / "target/old-build/release/monokl", "new": ROOT / "target/release/monokl"}
query = sys.argv[1] if len(sys.argv) > 1 else "needle"
runs = int(sys.argv[2]) if len(sys.argv) > 2 else 15
times = {name: [] for name in bins}
for i in range(runs + 2):
    for name, binary in bins.items():
        start = time.perf_counter()
        subprocess.run([str(binary), "search", query, "."], cwd=DIR, capture_output=True)
        if i >= 2:
            times[name].append((time.perf_counter() - start) * 1000)
for name, values in times.items():
    print(f"{name}: p50 {statistics.median(values):.1f} ms, min {min(values):.1f} ms")

